-- Secret-bank hint decks — the remaining 9 packs (item 21 cont.). Same shape
-- as the family pack in 20260928090000: 10 ordered hints per bank secret,
-- ramp = fog (0-1) -> decoy story (2-4) -> correction (5-7) -> near-solvable
-- (8-9), ~6 text / 3 emoji / 1 image (lucide:<name>). Decks matched to
-- secret_bank rows by (category, locale, text); emoji/image rows use locale
-- '*' and match either language. Idempotent (on conflict do nothing).

-- =========================================================================
-- KIDS
-- =========================================================================
with s as (
  select b.id, m.handle, m.locale
  from public.secret_bank b
  join (values
    ('kid-stuffed-animal',      'kids','en','I still sleep with a stuffed animal.'),
