  on h.handle = s.handle and (h.locale = s.locale or h.locale = '*')
on conflict (secret_bank_id, position) do nothing;

-- =========================================================================
-- WHOLESOME  (decoy usually reads darker/odder than the kind truth)
-- =========================================================================
with s as (
  select b.id, m.handle, m.locale
  from public.secret_bank b
  join (values
    ('whl-keep-cards',        'wholesome','en','I still keep every birthday card anyone has ever given me.'),
    ('whl-keep-cards',        'wholesome','fr','Je garde encore toutes les cartes d''anniversaire qu''on m''a offertes.'),
    ('whl-talk-to-bees',      'wholesome','en','I talk to bees in the garden and wish them a good day.'),
    ('whl-talk-to-bees',      'wholesome','fr','Je parle aux abeilles dans le jardin et je leur souhaite une bonne journée.'),
    ('whl-friend-playlist',   'wholesome','en','I have a playlist named after a friend for when I miss them.'),
    ('whl-friend-playlist',   'wholesome','fr','J''ai une playlist au nom d''un ami pour quand il me manque.'),
    ('whl-card-trick-kid',    'wholesome','en','I learned a card trick just to show one specific kid.'),
    ('whl-card-trick-kid',    'wholesome','fr','J''ai appris un tour de cartes juste pour le montrer à un enfant en particulier.'),
    ('whl-porch-light',       'wholesome','en','I leave the porch light on for a neighbour who works late.'),
    ('whl-porch-light',       'wholesome','fr','Je laisse la lumière du perron allumée pour un voisin qui rentre tard.'),
    ('whl-name-plants',       'wholesome','en','I name every plant I own.'),
    ('whl-name-plants',       'wholesome','fr','Je donne un prénom à chacune de mes plantes.'),
    ('whl-comfort-show',      'wholesome','en','I have re-watched the same comfort show more than ten times.'),
    ('whl-comfort-show',      'wholesome','fr','J''ai revu plus de dix fois la même série doudou.'),
    ('whl-strangers-note',    'wholesome','en','I keep a note on my phone of nice things strangers have said to me.'),
    ('whl-strangers-note',    'wholesome','fr','Je garde une note dans mon téléphone des gentillesses que des inconnus m''ont dites.'),
    ('whl-bake-no-words',     'wholesome','en','I bake for people when I do not know what else to say.'),
    ('whl-bake-no-words',     'wholesome','fr','Je fais des gâteaux pour les gens quand je ne sais pas quoi dire d''autre.'),
    ('whl-leaky-mug',         'wholesome','en','I still use a mug a friend made me even though it leaks.'),
    ('whl-leaky-mug',         'wholesome','fr','J''utilise encore une tasse qu''un ami a faite même si elle fuit.'),
    ('whl-gave-coat',         'wholesome','en','I gave a stranger my coat, never got it back, and do not mind.'),
