with s as (
  select b.id, m.handle, m.locale
  from public.secret_bank b
  join (values
    ('awk-wave-wrong',          'awkward','en','I have waved back at someone who was waving at the person behind me.'),
    ('awk-wave-wrong',          'awkward','fr','J''ai fait signe à quelqu''un qui saluait la personne derrière moi.'),
    ('awk-teacher-mum',         'awkward','en','I have called a teacher "mum" or "dad" out loud.'),
