    ('awk-practise-own-name',   'awkward','en','I have practised saying my own name after forgetting how it sounds.'),
    ('awk-practise-own-name',   'awkward','fr','J''ai répété mon propre prénom après avoir oublié comment il sonnait.'),
    ('awk-hid-aisle',           'awkward','en','I have hidden in an aisle to avoid saying hi to someone.'),
