    ('awk-hbd-wrong-msg',       'awkward','en','I have replied "happy birthday" to a message that was not that.'),
    ('awk-hbd-wrong-msg',       'awkward','fr','J''ai répondu « joyeux anniversaire » à un message qui n''en était pas un.'),
    ('awk-clapped-plane',       'awkward','en','I once clapped when the plane landed and no one joined.'),
