    ('awk-clapped-funeral',     'awkward','en','I clapped alone at a funeral by reflex.'),
    ('awk-clapped-funeral',     'awkward','fr','J''ai applaudi tout seul à un enterrement, par réflexe.'),
    ('awk-wave-minute',         'awkward','en','I waved back at someone for a full minute who was not waving at me.'),
    ('awk-wave-minute',         'awkward','fr','J''ai fait signe une minute entière à quelqu''un qui ne me saluait pas.'),
    ('awk-screenshot-self',     'awkward','en','I sent a screenshot of a person to that exact person.'),
    ('awk-screenshot-self',     'awkward','fr','J''ai envoyé la capture d''une personne à cette personne exactement.'),
    ('awk-fake-pregnancy',      'awkward','en','I congratulated a stranger on a pregnancy that was not one.'),
    ('awk-fake-pregnancy',      'awkward','fr','J''ai félicité une inconnue pour une grossesse qui n''en était pas une.'),
    ('awk-blanked-groom',       'awkward','en','I gave a best-man speech and blanked on the groom''s name.'),
    ('awk-blanked-groom',       'awkward','fr','J''ai fait un discours de témoin en oubliant le prénom du marié.'),
