    ('awk-liked-2014',          'awkward','fr','J''ai liké une photo de 2014 en pleine exploration d''un profil.'),
    ('awk-glass-door-interview','awkward','en','I walked into a glass door at a job interview and still got hired.'),
    ('awk-glass-door-interview','awkward','fr','Je me suis pris une porte vitrée à un entretien et j''ai quand même été embauché.'),
