    ('awk-wrong-weekend-wedding','awkward','fr','J''ai confirmé pour un mariage et je me suis présenté le mauvais week-end.'),
    ('awk-toast-wrong-table',   'awkward','en','I gave a toast at the wrong table at a stranger''s wedding.'),
    ('awk-toast-wrong-table',   'awkward','fr','J''ai porté un toast à la mauvaise table au mariage d''un inconnu.'),
    ('awk-group-email-oops',    'awkward','en','I replied to a group email with something meant for one person.'),
    ('awk-group-email-oops',    'awkward','fr','J''ai répondu à un mail groupé avec un message destiné à une seule personne.'),
    ('awk-colleague-name-2yr',  'awkward','en','I got a colleague''s name wrong for two years before anyone said.'),
    ('awk-colleague-name-2yr',  'awkward','fr','Je me suis trompé de prénom sur un collègue pendant deux ans avant qu''on me corrige.'),
    ('awk-asleep-woke-talking', 'awkward','en','I fell asleep in a meeting and woke myself up talking.'),
    ('awk-asleep-woke-talking', 'awkward','fr','Je me suis endormi en réunion et je me suis réveillé en parlant.'),
    ('awk-hug-handshake-leaving','awkward','en','I hugged someone going for a handshake at my own leaving do.'),
    ('awk-hug-handshake-leaving','awkward','fr','J''ai enlacé quelqu''un qui me tendait la main, à mon propre pot de départ.'),
    ('awk-hbd-wrong-person',    'awkward','en','I loudly sang "happy birthday" to the wrong person at the table.'),
    ('awk-hbd-wrong-person',    'awkward','fr','J''ai chanté « joyeux anniversaire » très fort à la mauvaise personne à table.')
  ) as m(handle, category, locale, secret_text)
    on m.category = b.category and m.locale = b.locale and m.secret_text = b.text
)
