  ('awk-hug-handshake-leaving','fr',0,'text','J''ai mal calé un geste d''au revoir à un événement qui portait littéralement sur mon départ.',null),
  ('awk-hug-handshake-leaving','fr',2,'text','Tout le monde faisait la queue pour dire un mot gentil, un par un.',null),
