  ('awk-hbd-wrong-person','*',8,'emoji','je chante fort ➡️ vers la mauvaise personne à table',null),
  ('awk-hbd-wrong-person','en',0,'text','I once led a song, loudly, aimed at completely the wrong face.',null),
  ('awk-hbd-wrong-person','en',2,'text','It was in a restaurant, cake incoming, everyone looking to me to start.',null),
  ('awk-hbd-wrong-person','en',4,'text','You might think I forgot whose birthday it was mid-song.',null),
  ('awk-hbd-wrong-person','en',5,'text','I knew whose birthday it was. I just turned to the person opposite them.',null),
  ('awk-hbd-wrong-person','en',7,'text','That person did a small confused wave while the actual birthday one waited.',null),
  ('awk-hbd-wrong-person','en',9,'text','I loudly sang "happy birthday" straight at the wrong person at the table.',null),
  ('awk-hbd-wrong-person','fr',0,'text','J''ai un jour lancé une chanson, fort, en visant le mauvais visage.',null),
  ('awk-hbd-wrong-person','fr',2,'text','C''était au restaurant, le gâteau arrivait, tout le monde attendait que je commence.',null),
  ('awk-hbd-wrong-person','fr',4,'text','Tu penserais que j''ai oublié de qui c''était l''anniversaire en pleine chanson.',null),
  ('awk-hbd-wrong-person','fr',5,'text','Je savais de qui c''était l''anniversaire. Je me suis juste tourné vers la personne en face.',null),
  ('awk-hbd-wrong-person','fr',7,'text','Cette personne a fait un petit signe confus pendant que le vrai fêté attendait.',null),
