  select b.id, m.handle, m.locale
  from public.secret_bank b
  join (values
    ('wp-mute-lunch',           'work_party','en','I have muted a meeting to finish my lunch.'),
    ('wp-mute-lunch',           'work_party','fr','J''ai coupé mon micro en réunion pour finir mon repas.'),
    ('wp-circle-back',          'work_party','en','I have said "let me circle back" with no intention of circling back.'),
