    ('wp-off-on-credit',        'work_party','fr','J''ai réglé un bug en redémarrant et je me suis attribué tout le mérite.'),
    ('wp-notes-complaints',     'work_party','en','I have a document titled "notes" that is just complaints.'),
    ('wp-notes-complaints',     'work_party','fr','J''ai un document intitulé « notes » qui n''est que des plaintes.'),
