    ('wp-applied-curiosity',    'work_party','fr','J''ai postulé à un poste juste pour voir si j''aurais un entretien.'),
    ('wp-status-green-tea',     'work_party','en','I keep my status green while making tea for 20 minutes.'),
    ('wp-status-green-tea',     'work_party','fr','Je garde mon statut en vert pendant que je fais un thé de 20 minutes.'),
    ('wp-forgot-name-year',     'work_party','en','I have forgotten a colleague''s name for over a year.'),
    ('wp-forgot-name-year',     'work_party','fr','J''ai oublié le prénom d''un collègue depuis plus d''un an.'),
    ('wp-cold-slide',           'work_party','en','I have presented a slide I did not read until that moment.'),
