    ('wp-excel-lie',            'work_party','en','I got the job by lying about knowing Excel.'),
    ('wp-excel-lie',            'work_party','fr','J''ai eu le poste en mentant sur mon niveau d''Excel.'),
    ('wp-reply-all-company',    'work_party','en','I once replied all to the entire company by accident.'),
    ('wp-reply-all-company',    'work_party','fr','J''ai déjà répondu « à tous » à toute l''entreprise par erreur.'),
    ('wp-dated-report',         'work_party','en','I have dated someone I directly managed.'),
    ('wp-dated-report',         'work_party','fr','J''ai déjà fréquenté une personne que je dirigeais directement.'),
    ('wp-ghost-quit',           'work_party','en','I quit a job by simply never going back.'),
    ('wp-ghost-quit',           'work_party','fr','J''ai quitté un job en n''y retournant simplement jamais.'),
    ('wp-forwarded-to-boss',    'work_party','en','I forwarded a complaint about my boss to my boss.'),
    ('wp-forwarded-to-boss',    'work_party','fr','J''ai transféré à mon chef une plainte qui le visait.'),
    ('wp-promoted-others-work', 'work_party','en','I was promoted for a project that was mostly someone else''s.'),
    ('wp-promoted-others-work', 'work_party','fr','J''ai été promu pour un projet qui était surtout celui de quelqu''un d''autre.'),
    ('wp-stairwell-cry',        'work_party','en','I have cried in a stairwell and walked back in smiling.'),
    ('wp-stairwell-cry',        'work_party','fr','J''ai pleuré dans une cage d''escalier et je suis revenu en souriant.'),
    ('wp-lowest-paid-silent',   'work_party','en','I learned I was the lowest paid on the team and said nothing for a year.'),
    ('wp-lowest-paid-silent',   'work_party','fr','J''ai découvert que j''étais le moins payé de l''équipe et je n''ai rien dit pendant un an.'),
    ('wp-slept-client-pres',    'work_party','en','I slept through a client presentation I was leading.'),
    ('wp-slept-client-pres',    'work_party','fr','J''ai dormi pendant une présentation client que je dirigeais.'),
