    ('wp-fake-reference',       'work_party','fr','J''ai mis une fausse référence sur mon CV et personne n''a jamais appelé.'),
    ('wp-fired-day-one',        'work_party','en','I was fired on my first day.'),
    ('wp-fired-day-one',        'work_party','fr','J''ai été viré le premier jour.'),
    ('wp-competitor-lunch',     'work_party','en','I have interviewed at a competitor on my lunch break.'),
    ('wp-competitor-lunch',     'work_party','fr','J''ai passé un entretien chez un concurrent pendant ma pause déjeuner.'),
    ('wp-screenshot-to-them',   'work_party','en','I sent a screenshot of a chat to the person in the chat.'),
    ('wp-screenshot-to-them',   'work_party','fr','J''ai envoyé la capture d''une conversation à la personne concernée.'),
    ('wp-own-bug-credit',       'work_party','en','I took credit for fixing a bug I had caused.'),
    ('wp-own-bug-credit',       'work_party','fr','Je me suis attribué la correction d''un bug que j''avais causé.'),
    ('wp-secret-nemesis',       'work_party','en','I have a work nemesis who has no idea.'),
    ('wp-secret-nemesis',       'work_party','fr','J''ai un ennemi juré au travail qui n''en a aucune idée.'),
    ('wp-security-walkout',     'work_party','en','I was walked out by security after resigning.'),
    ('wp-security-walkout',     'work_party','fr','Je me suis fait raccompagner par la sécurité après ma démission.'),
    ('wp-unread-meeting',       'work_party','en','I ran a meeting about a document I had not read.'),
    ('wp-unread-meeting',       'work_party','fr','J''ai animé une réunion sur un document que je n''avais pas lu.'),
    ('wp-paid-to-leave',        'work_party','en','I have been paid to leave a job quietly.'),
    ('wp-paid-to-leave',        'work_party','fr','On m''a payé pour quitter un poste discrètement.'),
    ('wp-applied-managers-role','work_party','en','I applied for my manager''s role without telling them.'),
    ('wp-applied-managers-role','work_party','fr','J''ai postulé au poste de mon manager sans le lui dire.'),
    ('wp-work-party-partner',   'work_party','en','I met my partner at a work party and we hid it for a year.'),
    ('wp-work-party-partner',   'work_party','fr','J''ai rencontré mon/ma partenaire à une fête du bureau et on l''a caché un an.')
  ) as m(handle, category, locale, secret_text)
    on m.category = b.category and m.locale = b.locale and m.secret_text = b.text
)
