    ('guy-wrote-off-car',      'guys_night','fr','J''ai bousillé une voiture en frimant sur un parking vide.'),
    ('guy-scar-3-stories',     'guys_night','en','I have a scar I tell three different stories about.'),
    ('guy-scar-3-stories',     'guys_night','fr','J''ai une cicatrice sur laquelle je raconte trois histoires différentes.'),
    ('guy-month-rent-bet',     'guys_night','en','I lost a month''s rent on a single bet.'),
    ('guy-month-rent-bet',     'guys_night','fr','J''ai perdu un mois de loyer sur un seul pari.'),
