)
insert into public.secret_bank_hints (secret_bank_id, position, kind, text, image_ref)
select s.id, h.position, h.kind, h.text, h.image_ref
from s
join (values
  ('guy-is-it-normal','*',1,'emoji','🔎🤔'::text,null::text),
  ('guy-is-it-normal','*',3,'emoji','📱🙈',null),
  ('guy-is-it-normal','*',6,'image',null,'lucide:search'),
  ('guy-is-it-normal','*',8,'emoji','barre de recherche : "est-ce normal que..."',null),
