  ('guy-festival-no-bands','en',7,'text','I spent three days on a camp chair by the tents and had a great time.',null),
  ('guy-festival-no-bands','en',9,'text','I went to a festival and saw not a single band.',null),
  ('guy-festival-no-bands','fr',0,'text','J''ai été à un grand événement musical et, si tu demandais, je ne pourrais pas citer l''affiche.',null),
