  ('guy-speeding-to-lesson','en',5,'text','I was still learning. I was on my way to be taught how to drive properly.',null),
  ('guy-speeding-to-lesson','en',7,'text','I had to hand the letter to the same instructor I was about to have a lesson with.',null),
